SELECT

FROM (
    SELECT

    FROM ai_messages
    WHERE conversation_id = #{conversationId}
      AND tenant_id = #{tenantId}
    ORDER BY create_time DESC
    LIMIT #{limit}
) t
ORDER BY create_time ASC

