    citations_json = #{citationsJson},
    tool_calls_json = #{toolCallsJson},
    status = #{status}
WHERE id = #{id}
  AND conversation_id = #{conversationId}
  AND tenant_id = #{tenantId}
  AND status = 'streaming'

