mapper.select:
SELECT

FROM ai_messages
WHERE conversation_id = #{conversationId}
  AND tenant_id = #{tenantId}
  AND (role = 'user' OR (role = 'assistant' AND status = 'complete'))
  AND content IS NOT NULL
  AND content <> ''

    AND id > #{afterId}


    AND id < #{beforeId}

ORDER BY create_time ASC, id ASC
LIMIT #{limit}
